#!/usr/bin/env node
/**
 * tree-probe.mjs — read the LIVE flash tree from the filesystem.
 *
 * T-WEBINSTALL-READINESS-GATE-TREE-BINDING. Before this module the readiness
 * gate read exactly ONE file — `docs/flash-matrix.json` — and never touched
 * `channels/` or `releases/desktop-flash/` at gate time. A tree with no
 * channels at all still gated PASS, because the matrix *claimed* `packed=4`.
 * The matrix was being trusted as the source of truth.
 *
 * It is not. The matrix is a convenience projection of the tree, generated by
 * `scripts/gen-flash-matrix.mjs`. These helpers probe the tree directly, so the
 * gate can re-derive what is actually on disk and FAIL when the projection
 * disagrees with reality.
 *
 * NOTHING HERE DECIDES FRESHNESS. That rule lives in exactly one place,
 * `scripts/channel-freshness.mjs` (`checkChannelFreshness`); this module only
 * *reads values* — the `<product>-latest` pointer target, the stamps present
 * under `releases/desktop-flash/`, and the channel's `manifest.json` claims —
 * and hands them to that predicate. Forking a second copy of the rule is
 * exactly what the gate must not do.
 *
 * READ-ONLY BY CONSTRUCTION: every function here only calls `existsSync`,
 * `lstatSync`, `readdirSync`, `readFileSync`, `realpathSync` or `openSync`
 * with the `r` flag. Nothing writes, creates, renames, or unlinks.
 *
 * FAIL CLOSED: a missing/unreadable file is reported as absent (`null`), never
 * invented and never assumed current. Callers must treat absence as a failure.
 *
 * HONESTY: `BOOT_VERIFIED=false`. Probing the tree proves what is PACKED and
 * what the pointers NAME — never that any image boots, and never a live flash.
 */

import { existsSync, lstatSync, readdirSync, readFileSync, readlinkSync, realpathSync } from "node:fs";
import { basename, join } from "node:path";

/** The files a packed channel must contain for an installer to flash it. */
export const REQUIRED_CHANNEL_FILES = Object.freeze([
  "manifest.json",
  "files.txt",
  "SHA256SUMS",
  "avb_pkmd.bin",
]);

const STAMP_RE = /^([a-z0-9]+)-([0-9]{8})-([0-9]{6})$/;

/** True when `path` is a symlink (never throws on absence). */
function isSymlink(path) {
  try {
    return lstatSync(path).isSymbolicLink();
  } catch {
    return false;
  }
}

/** True when `path` is a real directory (never throws on absence). */
function isDirectory(path) {
  try {
    return lstatSync(path).isDirectory();
  } catch {
    return false;
  }
}

/** A single unambiguous canonical path: the installer root the probe is bound to. */
export function makeRoots(installerRoot, releasesDir) {
  return { installerRoot, channelsRoot: join(installerRoot, "channels"), releasesDir };
}

/**
 * Probe one packed channel dir on disk. Read-only.
 *
 * `packed` is true only when the directory exists AND every required file is
 * present — the same "can this actually flash anything?" question the gate asks.
 *
 * @param {{installerRoot:string}} roots
 * @param {string} product
 * @returns {{product:string, dir:string, exists:boolean, packed:boolean,
 *   requiredFiles:string[], missingFiles:string[], missingRequired:string[],
 *   manifest:Record<string, unknown>|null, manifestError:string|null}}
 */
export function probeChannel(roots, product) {
  const dir = join(roots.channelsRoot, product);
  const requiredFiles = REQUIRED_CHANNEL_FILES;
  const result = {
    product,
    dir: `channels/${product}`,
    exists: isDirectory(dir),
    packed: false,
    requiredFiles,
    missingFiles: [],
    missingRequired: [],
    manifest: null,
    manifestError: null,
  };
  if (!result.exists) {
    // A product the matrix calls packed but which has no dir on disk flashes
    // nothing: every required file is missing.
    result.missingFiles = [...requiredFiles];
    result.missingRequired = [...requiredFiles];
    return result;
  }

  result.missingFiles = requiredFiles.filter((name) => !existsSync(join(dir, name)));
  result.missingRequired = requiredFiles.filter((name) => result.missingFiles.includes(name));

  const manifestPath = join(dir, "manifest.json");
  if (existsSync(manifestPath)) {
    try {
      const parsed = JSON.parse(readFileSync(manifestPath, "utf8"));
      result.manifest =
        parsed !== null && typeof parsed === "object" ? parsed : null;
      if (result.manifest === null) result.manifestError = "manifest.json is not a JSON object";
    } catch (err) {
      result.manifestError = `manifest.json is unreadable: ${err instanceof Error ? err.message : String(err)}`;
    }
  }

  result.packed = result.exists && result.missingFiles.length === 0;
  return result;
}

/**
 * Re-resolve the `<product>-latest` pointer from disk. Read-only.
 *
 * @returns {{name:string, present:boolean, isSymlink:boolean, target:string|null,
 *   targetExists:boolean, error:string|null}}
 */
export function resolveLatestPointer(roots, product) {
  const name = `${product}-latest`;
  const path = join(roots.releasesDir, name);
  const out = {
    name,
    present: false,
    isSymlink: false,
    target: null,
    targetExists: false,
    error: null,
  };
  if (!existsSync(path)) return out;
  out.present = true;
  out.isSymlink = isSymlink(path);
  try {
    // realpathSync resolves a symlink chain; falling back to the basename keeps
    // a regular directory named `<product>-latest` observable rather than
    // silently treated as "no pointer".
    out.target = out.isSymlink ? basename(realpathSync(path)) : basename(path);
  } catch (err) {
    out.error = `pointer ${name} is dangling or unresolvable: ${err instanceof Error ? err.message : String(err)}`;
    return out;
  }
  if (out.target !== null && out.isSymlink) {
    out.targetExists = isDirectory(join(roots.releasesDir, out.target));
  }
  return out;
}

/**
 * Read the stamp directories present under `releases/desktop-flash/`. Read-only.
 *
 * Pointers (`<product>-latest`, `latest.quarantined-*`) and non-stamp dirs are
 * skipped: a stamp is a REAL directory whose name parses as
 * `<product>-YYYYMMDD-HHMMSS`.
 *
 * @param {{releasesDir:string}} roots
 * @param {string|null} [product] restrict to one product
 * @returns {string[]} sorted stamp names
 */
export function listStampsOnDisk(roots, product = null) {
  if (!isDirectory(roots.releasesDir)) return [];
  let entries;
  try {
    entries = readdirSync(roots.releasesDir);
  } catch {
    return [];
  }
  const stamps = [];
  for (const entry of entries) {
    const match = STAMP_RE.exec(entry);
    if (match === null) continue;
    if (product !== null && match[1] !== product) continue;
    if (!isDirectory(join(roots.releasesDir, entry))) continue;
    stamps.push(entry);
  }
  stamps.sort((a, b) => a.localeCompare(b));
  return stamps;
}

/**
 * Enumerate the channel directories actually present on disk. Read-only.
 *
 * @returns {string[]} product names, sorted
 */
export function listChannelDirs(roots) {
  if (!isDirectory(roots.channelsRoot)) return [];
  let entries;
  try {
    entries = readdirSync(roots.channelsRoot);
  } catch {
    return [];
  }
  return entries
    .filter((entry) => !entry.startsWith("."))
    .filter((entry) => isDirectory(join(roots.channelsRoot, entry)))
    .sort((a, b) => a.localeCompare(b));
}

/**
 * Re-read a channel's manifest CLAIM (sourceStamp/releaseId/unixEpoch) from
 * disk, rather than trusting the matrix's copy of the same fields.
 *
 * @returns {{ok:boolean, sourceStamp:string|null, releaseId:string|null,
 *   unixEpoch:number|null, error:string|null}}
 */
export function readManifestClaim(probe) {
  const manifest = probe.manifest;
  if (manifest === null) {
    return {
      ok: false,
      sourceStamp: null,
      releaseId: null,
      unixEpoch: null,
      error: probe.manifestError ?? "manifest.json missing",
    };
  }
  const sourceStamp = typeof manifest.sourceStamp === "string" ? manifest.sourceStamp : null;
  const releaseId = typeof manifest.releaseId === "string" ? manifest.releaseId : null;
  const unixEpoch = typeof manifest.unixEpoch === "number" ? manifest.unixEpoch : null;
  const missing = [];
  if (sourceStamp === null) missing.push("sourceStamp");
  if (releaseId === null) missing.push("releaseId");
  if (unixEpoch === null) missing.push("unixEpoch");
  return {
    ok: missing.length === 0,
    sourceStamp,
    releaseId,
    unixEpoch,
    error: missing.length === 0 ? null : `manifest.json lacks ${missing.join(", ")}`,
  };
}

/**
 * Identity of an artifact path as a future re-check will see it, so the gate can
 * prove the bytes did not move underneath it. Read-only.
 *
 * Symlinks are described by their LINK (never followed), so re-pointing or
 * retargeting a channel artifact — exactly how a tree is repacked — is caught
 * as "changed during the gate" even if the link target keeps the same inode.
 *
 * @returns {{link:string|null, dev:number, ino:number, size:number, mtimeMs:number}|null}
 */
export function fileIdentity(path) {
  try {
    const st = lstatSync(path);
    const link = st.isSymbolicLink() ? readlinkSync(path) : null;
    return { link, dev: Number(st.dev), ino: Number(st.ino), size: st.size, mtimeMs: st.mtimeMs };
  } catch {
    return null;
  }
}
